class SalaryCalculator {
	calculate(employee: Employee): number {
		if (employee.role === "developer") {
			return employee.base > 3000 ? employee.base * 0.8 : employee.base * 0.9;
		}
		if (employee.role === "dba") {
			return employee.base > 2500 ? employee.base * 0.75 : employee.base * 0.85;
		}
		// one more block for every new role
		throw new Error("unknown role");
	}
}

